def solve_nqueens_5():
    n = 5
    # fixed: row 1 col 2
    fixed = {1: 2}

    # backtracking
    cols = [-1] * n

    def is_safe(row, col):
        for r in range(row):
            c = cols[r]
            if c == col:
                return False
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True
        if row in fixed:
            col = fixed[row]
            if is_safe(row, col):
                cols[row] = col
                if backtrack(row + 1):
                    return True
                cols[row] = -1
            return False
        for col in range(n):
            if is_safe(row, col):
                cols[row] = col
                if backtrack(row + 1):
                    return True
                cols[row] = -1
        return False

    if backtrack(0):
        return cols
    return None

sol = solve_nqueens_5()
print(sol)

def verify(sol):
    n = len(sol)
    for i in range(n):
        for j in range(i+1, n):
            if sol[i] == sol[j] or abs(i-j) == abs(sol[i]-sol[j]):
                return False, (i, j)
    return True, None

sol = [0, 2, 4, 1, 3]
print(verify(sol))
